routine_definition:
BEGIN
  -- Invariant: original_full_name = the true LCR full name.
  --            full_name = preferred_name if set, else original_full_name (the display name).
  -- This lets the app's existing UI continue to use .full_name everywhere
  -- and automatically get the preferred-name display.

  IF TG_OP = 'INSERT' THEN
    -- If caller didn't set original_full_name, derive it from full_name
    IF NEW.original_full_name IS NULL OR NEW.original_full_name = '' THEN
      NEW.original_full_name := NEW.full_name;
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    -- LCR import sends full_name = true full name. Capture it into original_full_name.
    -- Detect LCR-style updates by: full_name changed AND matches the LCR-provided value.
    -- Simpler: if NEW.full_name contains more words than NEW.preferred_name (or is different from OLD.preferred_name), it's a fresh LCR name. Update original_full_name.
    -- Even simpler rule: if full_name differs from preferred_name on the NEW row, treat full_name as a fresh canonical name and capture it.
    IF NEW.preferred_name IS NOT NULL AND NEW.preferred_name <> '' AND NEW.full_name <> NEW.preferred_name THEN
      NEW.original_full_name := NEW.full_name;
    END IF;
  END IF;

  -- Now enforce display invariant: full_name = preferred_name if set, else original_full_name
  IF NEW.preferred_name IS NOT NULL AND NEW.preferred_name <> '' THEN
    NEW.full_name := NEW.preferred_name;
  ELSIF NEW.original_full_name IS NOT NULL AND NEW.original_full_name <> '' THEN
    NEW.full_name := NEW.original_full_name;
  END IF;

  RETURN NEW;
END;
